import { Injectable, computed, signal } from '@angular/core';
import { TmdbMovie, WatchItem } from './movie';

const STORAGE_KEY = 'watchlist';

@Injectable({ providedIn: 'root' })
export class WatchlistStore {
  private _items = signal<WatchItem[]>(
    (() => {
      try {
        return JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]');
      } catch {
        return [];
      }
    })()
  );

  readonly items = this._items.asReadonly();
  readonly watchedCount = computed(() => this._items().filter(m => m.watched).length);

  add(movie: TmdbMovie) {
    if (this._items().some(m => m.id === movie.id)) return;
    this._items.update(items => [...items, { ...movie, watched: false }]);
  }

  toggleWatched(movie: WatchItem) {
    this._items.update(items =>
      items.map(m => (m.id === movie.id ? { ...m, watched: !m.watched } : m))
    );
  }

  remove(movie: WatchItem) {
    this._items.update(items => items.filter(m => m.id !== movie.id));
  }
}
```

